import { test } from 'node:test'
import assert from 'node:assert/strict'
import { spawnSync } from 'node:child_process'
import { readFileSync } from 'node:fs'
import { RATING_SCALE, notchChange } from '../../src/ratings/notch.mjs'

test('AC-1: RATING_SCALE is frozen 19-entry array', (t) => {
  const expected = ['AAA', 'AA+', 'AA', 'AA-', 'A+', 'A', 'A-', 'BBB+', 'BBB', 'BBB-', 'BB+', 'BB', 'BB-', 'B+', 'B', 'B-', 'CCC+', 'CCC', 'CCC-']

  assert.deepStrictEqual(RATING_SCALE, expected)
  assert.equal(RATING_SCALE.length, 19)
  assert.equal(RATING_SCALE[0], 'AAA')
  assert.equal(RATING_SCALE[18], 'CCC-')
  assert.equal(RATING_SCALE.indexOf('BBB+'), 7)
  assert.equal(RATING_SCALE.indexOf('BB+'), 10)
  assert.ok(Array.isArray(RATING_SCALE))
  assert.equal(new Set(RATING_SCALE).size, 19)
  assert.ok(Object.isFrozen(RATING_SCALE))

  // Push should throw TypeError
  assert.throws(() => {
    RATING_SCALE.push('D')
  }, TypeError)

  // Assignment should throw TypeError
  assert.throws(() => {
    RATING_SCALE[0] = 'X'
  }, TypeError)

  // After tampering, should still be intact
  assert.equal(RATING_SCALE.length, 19)
  assert.equal(RATING_SCALE[0], 'AAA')
  assert.equal(notchChange('BBB+', 'BB+'), 3)
})

test('AC-2: notchChange(BBB+, BB+) returns 3', () => {
  assert.equal(notchChange('BBB+', 'BB+'), 3)
})

test('AC-3: notchChange(BB+, BBB+) returns -3', () => {
  assert.equal(notchChange('BB+', 'BBB+'), -3)
})

test('AC-4: Same rating returns +0 (not -0)', () => {
  assert.equal(notchChange('A', 'A'), 0)
  assert.ok(Object.is(notchChange('A', 'A'), 0))

  // Test all ratings
  for (const r of RATING_SCALE) {
    assert.equal(notchChange(r, r), 0)
    assert.ok(Object.is(notchChange(r, r), 0))
  }
})

test('AC-5: Adjacent steps return ±1', () => {
  assert.equal(notchChange('AAA', 'AA+'), 1)
  assert.equal(notchChange('A-', 'BBB+'), 1)
  assert.equal(notchChange('BBB-', 'BB+'), 1)
  assert.equal(notchChange('B-', 'CCC+'), 1)
  assert.equal(notchChange('CCC-', 'CCC-'), 0) // Same

  assert.equal(notchChange('BB+', 'BBB-'), -1)
})

test('AC-6: Extremes return 18 and -18', () => {
  assert.equal(notchChange('AAA', 'CCC-'), 18)
  assert.equal(notchChange('CCC-', 'AAA'), -18)
})

test('AC-7: All 361 pairs return j - i, antisymmetric', () => {
  for (let i = 0; i < RATING_SCALE.length; i++) {
    for (let j = 0; j < RATING_SCALE.length; j++) {
      const result = notchChange(RATING_SCALE[i], RATING_SCALE[j])
      const expected = j - i

      assert.equal(result, expected, `notchChange(${RATING_SCALE[i]}, ${RATING_SCALE[j]}) should equal ${expected}`)
      assert.equal(typeof result, 'number')
      assert.ok(Number.isInteger(result))
      assert.ok(result >= -18 && result <= 18)

      // Not a promise
      assert.ok(!(result instanceof Promise))

      // Same value on second call
      assert.equal(notchChange(RATING_SCALE[i], RATING_SCALE[j]), result)

      // Antisymmetric for different values
      if (i !== j) {
        assert.equal(notchChange(RATING_SCALE[i], RATING_SCALE[j]), -notchChange(RATING_SCALE[j], RATING_SCALE[i]))
      }
    }
  }
})

test('AC-8: Case-insensitive (toUpperCase, never toLocale*)', () => {
  assert.equal(notchChange('bbb+', 'bb+'), 3)
  assert.equal(notchChange('Bbb+', 'bB+'), 3)
  assert.equal(notchChange('aaa', 'ccc-'), 18)
  assert.equal(notchChange('a', 'A'), 0)
})

test('AC-9: trim() whitespace including U+00A0 and U+FEFF', () => {
  assert.equal(notchChange('  BBB+ ', '\tBB+\n'), 3)
  assert.equal(notchChange('  bbb+ ', 'BB+'), 3)

  // With U+00A0 (non-breaking space) and U+FEFF (BOM)
  assert.equal(notchChange(' A﻿', 'A'), 0)
})

test('AC-10: Unknown ratings throw RangeError', () => {
  const unknownRatings = ['D', 'C', 'CC', 'NR', 'AAA-', 'AAA+', 'BBB +', 'B B', 'BBB++', 'Baa1', 'AA−', 'АAA']

  for (const x of unknownRatings) {
    assert.throws(() => notchChange(x, 'A'), RangeError)
    assert.throws(() => notchChange('A', x), RangeError)
  }
})

test('AC-11: Empty/whitespace-only throw RangeError', () => {
  assert.throws(() => notchChange('', 'A'), RangeError)
  assert.throws(() => notchChange('A', ''), RangeError)

  assert.throws(() => notchChange('   ', 'A'), RangeError)
  assert.throws(() => notchChange('A', '   '), RangeError)

  assert.throws(() => notchChange('\n\t', 'A'), RangeError)
  assert.throws(() => notchChange('A', '\n\t'), RangeError)
})

